/**
 * A {@link Loader} for components extracted by Ghidra from a DYLD Cache
 */
public class DyldCacheExtractLoader : MachoLoader {

	public static string DYLD_CACHE_EXTRACT_NAME = "Extracted DYLD Component";

	static readonly string LIBOBJC_OPTION_NAME = "Add libobjc.dylib";
	static readonly bool LIBOBJC_OPTION_DEFAULT = true;

	static readonly string AUTH_DATA_OPTION_NAME = "Add AUTH_DATA";
	static readonly bool AUTH_DATA_OPTION_DEFAULT = false;

	static readonly string DIRTY_DATA_OPTION_NAME = "Add DIRTY_DATA";
	static readonly bool DIRTY_DATA_OPTION_DEFAULT = false;

	static readonly string CONST_DATA_OPTION_NAME = "Add CONST_DATA";
	static readonly bool CONST_DATA_OPTION_DEFAULT = true;

	static readonly string TEXT_STUBS_OPTION_NAME = "Add TEXT_STUBS";
	static readonly bool TEXT_STUBS_OPTION_DEFAULT = true;

	static readonly string CONFIG_DATA_OPTION_NAME = "Add CONFIG_DATA";
	static readonly bool CONFIG_DATA_OPTION_DEFAULT = false;

	static readonly string READ_ONLY_DATA_OPTION_NAME = "Add READ_ONLY_DATA";
	static readonly bool READ_ONLY_DATA_OPTION_DEFAULT = true;

	static readonly string CONST_TPRO_DATA_OPTION_NAME = "Add CONST_TPRO_DATA";
	static readonly bool CONST_TPRO_DATA_OPTION_DEFAULT = false;

	/* @Override */
	public Collection<LoadSpec> findSupportedLoadSpecs(ByteProvider provider)
    {
		if (provider.length() >= DyldCacheExtractor.FOOTER_V1.length) {
			if (Arrays.equals(DyldCacheExtractor.FOOTER_V1,
				provider.readBytes(provider.length() - DyldCacheExtractor.FOOTER_V1.length,
					DyldCacheExtractor.FOOTER_V1.length))) {
				return base.findSupportedLoadSpecs(provider);
			}
		}
		return List.of();
	}

	/* @Override */
	public void load(Program program, ImporterSettings settings)
    {

		try {
			FileBytes fileBytes =
				MemoryBlockUtils.createFileBytes(program, settings.provider(), settings.monitor());
			MachoExtractProgramBuilder.buildProgram(program, settings.provider(), fileBytes, false,
				settings.log(), settings.monitor());
			addOptionalComponents(program, settings.options(), settings.log(), settings.monitor());
		}
		catch (CancelledException e) {
			return;
		}
		catch (IOException e) {
			throw e;
		}
		catch (Exception e) {
			throw new IOException(e);
		}
	}

	/* @Override */
	protected void loadProgramInto(Program program, ImporterSettings settings)
    {
		FSRL fsrl = settings.provider().getFSRL();
		Group[] children = program.getListing().getDefaultRootModule().getChildren();
		if (Arrays.stream(children).anyMatch(e => e.getName().contains(fsrl.getPath()))) {
			settings.log().appendMsg("%s has already been added".formatted(fsrl.getPath()));
			return;
		}
		try {
			FileBytes fileBytes =
				MemoryBlockUtils.createFileBytes(program, settings.provider(), settings.monitor());
			MachoExtractProgramBuilder.buildProgram(program, settings.provider(), fileBytes, true,
				settings.log(), settings.monitor());
			addOptionalComponents(program, settings.options(), settings.log(), settings.monitor());
		}
		catch (CancelledException e) {
			return;
		}
		catch (IOException e) {
			throw e;
		}
		catch (Exception e) {
			throw new IOException(e);
		}
	}

	/* @Override */
	public bool supportsLoadIntoProgram(Program program) {
		return DYLD_CACHE_EXTRACT_NAME.equals(program.getExecutableFormat());
	}

	/* @Override */
	public string getName() {
		return DYLD_CACHE_EXTRACT_NAME;
	}

	/* @Override */
	public Collection<string> getAssociatedFileExtensions() {
		return List.of();
	}

	/* @Override */
	public int getTierPriority() {
		return 49; // Higher priority than MachoLoader
	}

	/* @Override */
	public List<Option> getDefaultOptions(ByteProvider provider, LoadSpec loadSpec,
			DomainObject domainObject, bool loadIntoProgram, bool mirrorFsLayout) {
		List<Option> list = new();
		list.add(Option.newBoolean(LIBOBJC_OPTION_NAME)
				.value(!loadIntoProgram && LIBOBJC_OPTION_DEFAULT)
				.commandLineArgument(createArg("-libobjc"))
				.build());
		list.add(Option.newBoolean(AUTH_DATA_OPTION_NAME)
				.value(!loadIntoProgram && AUTH_DATA_OPTION_DEFAULT)
				.commandLineArgument(createArg("-authData"))
				.build());
		list.add(Option.newBoolean(DIRTY_DATA_OPTION_NAME)
				.value(!loadIntoProgram && DIRTY_DATA_OPTION_DEFAULT)
				.commandLineArgument(createArg("-dirtyData"))
				.build());
		list.add(Option.newBoolean(CONST_DATA_OPTION_NAME)
				.value(!loadIntoProgram && CONST_DATA_OPTION_DEFAULT)
				.commandLineArgument(createArg("-constData"))
				.build());
		list.add(Option.newBoolean(TEXT_STUBS_OPTION_NAME)
				.value(!loadIntoProgram && TEXT_STUBS_OPTION_DEFAULT)
				.commandLineArgument(createArg("-textStubs"))
				.build());
		list.add(Option.newBoolean(CONFIG_DATA_OPTION_NAME)
				.value(!loadIntoProgram && CONFIG_DATA_OPTION_DEFAULT)
				.commandLineArgument(createArg("-configData"))
				.build());
		list.add(Option.newBoolean(READ_ONLY_DATA_OPTION_NAME)
				.value(!loadIntoProgram && READ_ONLY_DATA_OPTION_DEFAULT)
				.commandLineArgument(createArg("-readOnlyData"))
				.build());
		list.add(Option.newBoolean(CONST_TPRO_DATA_OPTION_NAME)
				.value(!loadIntoProgram && CONST_TPRO_DATA_OPTION_DEFAULT)
				.commandLineArgument(createArg("-constTproData"))
				.build());
		return list;
	}

	/* @Override */
	public string validateOptions(ByteProvider provider, LoadSpec loadSpec, List<Option> options,
			Program program) {
		if (options != null) {
			foreach (Option option in options) {
				string name = option.getName();
				if (name.equals(LIBOBJC_OPTION_NAME) || name.equals(AUTH_DATA_OPTION_NAME) ||
					name.equals(DIRTY_DATA_OPTION_NAME) || name.equals(CONST_DATA_OPTION_NAME) ||
					name.equals(TEXT_STUBS_OPTION_NAME) || name.equals(CONFIG_DATA_OPTION_NAME) ||
					name.equals(READ_ONLY_DATA_OPTION_NAME) ||
					name.equals(CONST_TPRO_DATA_OPTION_NAME)) {
					if (!typeof(Boolean).isAssignableFrom(option.getValueClass())) {
						return "Invalid type for option: " + name + " - " + option.getValueClass();
					}
				}
			}
		}
		return null;
	}

	/* @Override */
	protected bool isLoadLibraries(ImporterSettings settings) {
		return false;
	}

	/* @Override */
	protected bool shouldSearchAllPaths(Program program, ImporterSettings settings) {
		return false;
	}

	/* @Override */
	protected void postLoadProgramFixups(List<Loaded<Program>> loadedPrograms,
			ImporterSettings settings)
    {
		// Do nothing
	}

	private void addOptionalComponents(Program program, List<Option> options, MessageLog log,
			TaskMonitor monitor)
    {
		bool addLibobjc =
			OptionUtils.getOption(LIBOBJC_OPTION_NAME, options, LIBOBJC_OPTION_DEFAULT);
		long flags = 0;
		if (OptionUtils.getOption(AUTH_DATA_OPTION_NAME, options, AUTH_DATA_OPTION_DEFAULT)) {
			flags |= DyldCacheMappingAndSlideInfo.DYLD_CACHE_MAPPING_AUTH_DATA;
		}
		if (OptionUtils.getOption(DIRTY_DATA_OPTION_NAME, options, DIRTY_DATA_OPTION_DEFAULT)) {
			flags |= DyldCacheMappingAndSlideInfo.DYLD_CACHE_MAPPING_DIRTY_DATA;
		}
		if (OptionUtils.getOption(CONST_DATA_OPTION_NAME, options, CONST_DATA_OPTION_DEFAULT)) {
			flags |= DyldCacheMappingAndSlideInfo.DYLD_CACHE_MAPPING_CONST_DATA;
		}
		if (OptionUtils.getOption(TEXT_STUBS_OPTION_NAME, options, TEXT_STUBS_OPTION_DEFAULT)) {
			flags |= DyldCacheMappingAndSlideInfo.DYLD_CACHE_MAPPING_TEXT_STUBS;
		}
		if (OptionUtils.getOption(CONFIG_DATA_OPTION_NAME, options, CONFIG_DATA_OPTION_DEFAULT)) {
			flags |= DyldCacheMappingAndSlideInfo.DYLD_CACHE_DYNAMIC_CONFIG_DATA;
		}
		if (OptionUtils.getOption(READ_ONLY_DATA_OPTION_NAME, options,
			READ_ONLY_DATA_OPTION_DEFAULT)) {
			flags |= DyldCacheMappingAndSlideInfo.DYLD_CACHE_READ_ONLY_DATA;
		}
		if (OptionUtils.getOption(CONST_TPRO_DATA_OPTION_NAME, options,
			CONST_TPRO_DATA_OPTION_DEFAULT)) {
			flags |= DyldCacheMappingAndSlideInfo.DYLD_CACHE_MAPPING_CONST_TPRO_DATA;
		}
		if (!addLibobjc && flags == 0) {
			return;
		}
		using (FileSystemRef fsRef = openDyldCache(program, monitor))
{
			DyldCacheFileSystem fs = (DyldCacheFileSystem) fsRef.getFilesystem();
			Set<GFile> files = new();
			if (addLibobjc) {
				Optional.ofNullable(fs.lookup("/usr/lib/libobjc.A.dylib")).ifPresent(files.add);
			}
			files.addAll(fs.getFiles(flags));
			foreach (GFile file in files) {
				Group[] children = program.getListing().getDefaultRootModule().getChildren();
				if (Arrays.stream(children).anyMatch(e => e.getName().contains(file.getPath()))) {
					log.appendMsg("%s has already been added".formatted(file.getPath()));
					continue;
				}
				ByteProvider p = fs.getByteProvider(file, monitor);
				FileBytes fileBytes = MemoryBlockUtils.createFileBytes(program, p, monitor);
				MachoExtractProgramBuilder.buildProgram(program, p, fileBytes, true, log,
					monitor);
			}
		}
	}

	/**
	 * Attempts to open the given {@link Program}'s originating {@link DyldCacheFileSystem}
	 * 
	 * @param program The {@link Program}
	 * @param monitor A {@link TaskMonitor}
	 * @return A {@link FileSystemRef file system reference} to the open {@link DyldCacheFileSystem}
	 * @throws IOException if an FSRL or IO-related error occurred
	 * @throws CancelledException if the user cancelled the operation
	 */
	public static FileSystemRef openDyldCache(Program program, TaskMonitor monitor)
    {
		FSRL fsrl = FSRL.fromProgram(program);
		if (fsrl == null) {
			throw new IOException("The program does not have an FSRL property");
		}
		string requiredProtocol = DyldCacheFileSystem.DYLD_CACHE_FSTYPE;
		if (!fsrl.getFS().getProtocol().equals(requiredProtocol)) {
			throw new IOException("The program's FSRL protocol is '%s' but '%s' is required"
					.formatted(fsrl.getFS().getProtocol(), requiredProtocol));
		}
		FSRLRoot fsrlRoot = fsrl.getFS();
		return FileSystemService.getInstance().getFilesystem(fsrlRoot, monitor);
	}
}
